refentry.refsect1:
&reftitle.description;
arrayfalsenullfilter_var_array arrayarray arrayintoptionsFILTER_DEFAULT booladd_empty&true;
Функция фильтрует значения ассоциативного массива (&array;) фильтрами проверки — константами семейства FILTER_VALIDATE_*, очистки — семейства FILTER_SANITIZE_* — или пользовательскими фильтрами.

&reftitle.errors;
Функция выбрасывает ошибку TypeError, если в параметр options передали массив (&array;) с нестроковым (&string;) ключом, и ошибку ValueError, если массив опций содержит пустой ключ.
Начиная с PHP 8.5.0 функция выбрасывает исключение Filter\FilterFailedException, если для элемента массива array установили флаг FILTER_THROW_ON_FAILURE и значение не прошло фильтр, и ошибку ValueError, если для такого элемента флаг FILTER_THROW_ON_FAILURE указали вместе с флагом FILTER_NULL_ON_FAILURE.

&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     Функция теперь выбрасывает ошибку TypeError,
     если массив в параметре options содержит нестроковый (&string;) ключ,
     и ошибку ValueError,
     если в массив опций содержит пустой ключ; раньше выдавалось предупреждение
     E_WARNING и возвращалось значение &false;.

  &reftitle.examples;

   Пример фильтрации массива значений функцией filter_var_array

    Записи фильтруются как скалярные значения, если не указали флаг
    FILTER_REQUIRE_ARRAY или
    FILTER_FORCE_ARRAY.
    Поэтому флаг FILTER_REQUIRE_SCALAR у записи
    testscalar ниже лишь задаёт это поведение явно.



<?php

$data = [
    'product_id' => 'libgd<script>',
    'component'  => '10',
    'versions'   => '2.0.33',
    'testscalar' => ['2', '23', '10', '12'],
    'testarray'  => '2',
];

$filters = [
    'product_id'   => FILTER_SANITIZE_ENCODED,
    'component'    => [
        'filter'   => FILTER_VALIDATE_INT,
        'flags'    => FILTER_FORCE_ARRAY,
        'options'  => [
            'min_range' => 1,
            'max_range' => 10,
        ],
    ],
    'versions'     => [
        'filter' => FILTER_SANITIZE_ENCODED
    ],
    'testscalar'   => [
        'filter' => FILTER_VALIDATE_INT,
        'flags'  => FILTER_REQUIRE_SCALAR,
    ],
    'testarray'    => [
        'filter' => FILTER_VALIDATE_INT,
        'flags'  => FILTER_FORCE_ARRAY,
    ],
    'doesnotexist' => FILTER_VALIDATE_INT,
];

var_dump(filter_var_array($data, $filters));


   &example.outputs;


array(6) {
  ["product_id"]=>
  string(17) "libgd%3Cscript%3E"
  ["component"]=>
  array(1) {
    [0]=>
    int(10)
  }
  ["versions"]=>
  string(6) "2.0.33"
  ["testscalar"]=>
  bool(false)
  ["testarray"]=>
  array(1) {
    [0]=>
    int(2)
  }
  ["doesnotexist"]=>
  NULL
}




   Пример применения одного фильтра ко всем значениям функцией filter_var_array

    При передаче в параметр options целочисленного значения (&integer;)
    один и тот же фильтр применяется к каждой записи массива.



<?php

$data = [
    'name'  => '<b>John</b>',
    'email' => 'john@example<script>.com',
    'bio'   => 'Developer & writer',
];

var_dump(filter_var_array($data, FILTER_SANITIZE_SPECIAL_CHARS));


   &example.outputs;


array(3) {
  ["name"]=>
  string(27) "&#60;b&#62;John&#60;/b&#62;"
  ["email"]=>
  string(32) "john@example&#60;script&#62;.com"
  ["bio"]=>
  string(22) "Developer &#38; writer"
}




   Пример применения фильтра FILTER_CALLBACK функцией filter_var_array


<?php

$data = [
    'name'  => '  John Doe  ',
    'city'  => '  New York  ',
];

$options = [
    'name' => [
        'filter'  => FILTER_CALLBACK,
        'options' => 'trim',
    ],
    'city' => [
        'filter'  => FILTER_CALLBACK,
        'options' => function ($value) {
            return strtoupper(trim($value));
        },
    ],
];

var_dump(filter_var_array($data, $options));


   &example.outputs;


array(2) {
  ["name"]=>
  string(8) "John Doe"
  ["city"]=>
  string(8) "NEW YORK"
}
